CREATE TABLE IF NOT EXISTS users (name TEXT PRIMARY KEY COLLATE NOCASE, display TEXT NOT NULL, salt TEXT NOT NULL, hash TEXT NOT NULL, found TEXT NOT NULL DEFAULT '[]', ver INTEGER NOT NULL DEFAULT 0, share INTEGER NOT NULL DEFAULT 1, public INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (ip TEXT NOT NULL, t INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_ip ON attempts(ip, t);
